  let warm = vec3f(0.02, 0.008, -0.012) * uniforms.intensity;
  let rgb = clamp(content.rgb + vec3f(grain * uniforms.intensity) + warm, vec3f(0.0), vec3f(1.0));
  return vec4f(rgb, content.a);
